export default {
  props: {
    listObj: Array,
    className: {
      type: String,
      default: ''
    }
  },
  data() {
    return {
      isOrderedList: false,
      uniqueKey: Math.random().toString(36).substring(7)
    }
  },
  created: function() {
    switch (this.$props.className) {
      case 'decimal':
      case 'decimal-leading-zero':
      case 'upper-roman':
      case 'upper-alpha':
        this.isOrderedList = true;
    }
  }
}
